#!/usr/bin/env bash

set -eu

APP_DIR="${APP_DIR:-/app}"
DB_DRIVER="${DB_DRIVER:-sqlite}"
DATA_DIR_VALUE="${DATA_DIR:-/app/data}"
DB_INIT_MAX_RETRIES="${DB_INIT_MAX_RETRIES:-30}"
DB_INIT_RETRY_INTERVAL="${DB_INIT_RETRY_INTERVAL:-2}"

ensure_runtime_env_file() {
  if [ -f "${APP_DIR}/.env" ]; then
    return
  fi

  cat > "${APP_DIR}/.env" <<EOF
# Generated by docker runtime scripts so the install-state check can run inside containers.
EOF
}

configure_database_url() {
  if [ -n "${DATABASE_URL:-}" ]; then
    return
  fi

  case "${DB_DRIVER}" in
    sqlite)
      SQLITE_PATH_VALUE="${SQLITE_PATH:-/app/data/material_bin.db}"
      mkdir -p "$(dirname "${SQLITE_PATH_VALUE}")"
      export DATABASE_URL="sqlite:////${SQLITE_PATH_VALUE#/}"
      ;;
    mysql)
      MYSQL_HOST_VALUE="${MYSQL_HOST:-mysql}"
      MYSQL_PORT_VALUE="${MYSQL_PORT:-3306}"
      MYSQL_DATABASE_VALUE="${MYSQL_DATABASE:-material_bin}"
      MYSQL_USER_VALUE="${MYSQL_USER:-material_bin}"
      MYSQL_PASSWORD_VALUE="${MYSQL_PASSWORD:-material_bin}"
      export DATABASE_URL="mysql+pymysql://${MYSQL_USER_VALUE}:${MYSQL_PASSWORD_VALUE}@${MYSQL_HOST_VALUE}:${MYSQL_PORT_VALUE}/${MYSQL_DATABASE_VALUE}"
      ;;
    *)
      echo "Unsupported DB_DRIVER: ${DB_DRIVER}" >&2
      exit 1
      ;;
  esac
}

wait_for_database_command() {
  local command="$1"
  local attempt=1

  while ! python -c "${command}"; do
    if [ "${attempt}" -ge "${DB_INIT_MAX_RETRIES}" ]; then
      echo "Database command failed after ${attempt} attempts." >&2
      exit 1
    fi

    echo "Database not ready yet, retrying (${attempt}/${DB_INIT_MAX_RETRIES})..."
    attempt=$((attempt + 1))
    sleep "${DB_INIT_RETRY_INTERVAL}"
  done
}

prepare_runtime_environment() {
  mkdir -p "${DATA_DIR_VALUE}"
  configure_database_url
  ensure_runtime_env_file
}
